import 'package:flutter/material.dart';
void main()=>runApp(const App());
class C{static const p=Color(0xFF0F6B78),bg=Color(0xFFF5F8F8),text=Color(0xFF173033),muted=Color(0xFF6B7C80);static const ok=Color(0xFF4E9A6B);}
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Saffari NeuroCare',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:C.p),scaffoldBackgroundColor:C.bg),builder:(c,w)=>Directionality(textDirection:TextDirection.rtl,child:w!),home:const Login());}
class Login extends StatefulWidget{const Login({super.key});@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final phone=TextEditingController(),pass=TextEditingController();bool loading=false;@override void dispose(){phone.dispose();pass.dispose();super.dispose();}void go()async{if(phone.text.length<10||pass.text.length<4){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('شماره موبایل و رمز عبور را کامل وارد کنید.')));return;}setState(()=>loading=true);await Future.delayed(const Duration(milliseconds:300));if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Home()));}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const SizedBox(height:45),const Icon(Icons.psychology_alt_rounded,size:58,color:C.p),const SizedBox(height:18),const Text('SAFFARI NEUROCARE',style:TextStyle(fontSize:25,fontWeight:FontWeight.w900,color:C.p)),const SizedBox(height:6),const Text('مراقبت هوشمند، همراه با دکتر صفاری',style:TextStyle(color:C.muted)),const SizedBox(height:34),const Text('ورود به مسیر اختصاصی بیمار',style:TextStyle(fontSize:23,fontWeight:FontWeight.w800,color:C.text)),const SizedBox(height:18),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'شماره موبایل',prefixIcon:Icon(Icons.phone))),const SizedBox(height:12),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'رمز عبور',prefixIcon:Icon(Icons.lock))),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:loading?null:go,style:FilledButton.styleFrom(backgroundColor:C.p,padding:const EdgeInsets.all(16)),child:Text(loading?'در حال ورود...':'ورود'))),const SizedBox(height:12),const Text('پس از ورود، کد اتصال بیمار/کلینیک ثبت می‌شود.',style:TextStyle(fontSize:12,color:C.muted))]))));}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;final pages=const[Dashboard(),StatusPage(),TreatmentPage(),RecordPage(),AccountPage()];@override Widget build(BuildContext c)=>Scaffold(body:pages[tab],floatingActionButton:FloatingActionButton.extended(backgroundColor:C.p,foregroundColor:Colors.white,onPressed:()=>showDialog(context:c,builder:(_)=>const AppointmentDialog()),icon:const Icon(Icons.calendar_month),label:const Text('درخواست نوبت')),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'خانه'),NavigationDestination(icon:Icon(Icons.insights_outlined),label:'وضعیت من'),NavigationDestination(icon:Icon(Icons.medication_outlined),label:'درمان'),NavigationDestination(icon:Icon(Icons.folder_outlined),label:'پرونده'),NavigationDestination(icon:Icon(Icons.person_outline),label:'حساب من')]));}
