class StatusPage extends StatelessWidget{const StatusPage({super.key});@override Widget build(BuildContext c)=>Page(title:'وضعیت من',child:Column(children:[const CardX(title:'تعداد روزهای سردرد',body:'۷ روز در ماه',icon:Icons.calendar_today),const SizedBox(height:10),const CardX(title:'حملات شدید',body:'۲ حمله اخیر',icon:Icons.warning_amber),const SizedBox(height:10),const CardX(title:'داروی حمله',body:'۳ روز استفاده در ماه',icon:Icons.medication),const SizedBox(height:18),Container(height:170,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:CustomPaint(painter:ChartPainter()))]));}
class ChartPainter extends CustomPainter{@override void paint(Canvas x,Size s){final p=Paint()..color=C.p..strokeWidth=3..style=PaintingStyle.stroke;final pts=[Offset(10,s.height*.7),Offset(s.width*.22,s.height*.55),Offset(s.width*.42,s.height*.62),Offset(s.width*.62,s.height*.35),Offset(s.width*.82,s.height*.45),Offset(s.width-10,s.height*.25)];final path=Path()..moveTo(pts[0].dx,pts[0].dy);for(final q in pts.skip(1))path.lineTo(q.dx,q.dy);x.drawPath(path,p);}@override bool shouldRepaint(covariant CustomPainter old)=>false;}
